import{_ as i,o as a,c as n,ai as t}from"./chunks/framework.BxxKhjs3.js";const e="/pub-blog/assets/image-20250624000205754.yQI_UhKz.png",p="/pub-blog/assets/image-20250624000418732.Doi3KHdD.png",l="/pub-blog/assets/image-20250624000707881.CAQhasVD.png",h="/pub-blog/assets/image-20250624000734163.C-7mUEPp.png",k="/pub-blog/assets/image-20250624000807035.By5npW9d.png",r="/pub-blog/assets/0000000000011111111.20250620155133.75981077787316035971410601430804.Dd4c9cna.png",E="/pub-blog/assets/0000000000011111111.20250620155133.56282241275264687848543582566127.Cwsx6KY-.png",d="/pub-blog/assets/image-20250624001130167.Dqhb-LYl.png",g="/pub-blog/assets/image-20250622200325374.BLr7GNE1.png",A=JSON.parse(`{"title":"HarmonyOS Repeat 可复用的循环渲染","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS Repeat 可复用的循环渲染/HarmonyOS Repeat 可复用的循环渲染.md","filePath":"鸿蒙开发技巧/HarmonyOS Repeat 可复用的循环渲染/HarmonyOS Repeat 可复用的循环渲染.md","lastUpdated":1750695195000,"__rawMarkdown":"# HarmonyOS Repeat 可复用的循环渲染\\n\\n## 什么是Repeat\\n\\n类似懒加载 LazyForEach，都能提高长列表的渲染性能，都能实现组件的动态渲染和释放，节省内存。区别主要是：\\n\\n- Repeat直接监听状态变量的变化，而LazyForEach需要开发者实现[IDataSource](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-rendering-control-lazyforeach#idatasource)接口\\n\\n  Repeat使用起来要更加简单一些\\n\\n- Repeat还增强了节点复用能力，提高了长列表滑动和数据更新的渲染性能。\\n\\n  Repeat存在缓冲池，需要复用节点的时候可以从缓冲池中获取，LazyForEach是直接重新创建\\n\\n- Repeat增加了渲染模板（template）的能力，在同一个数组中，根据开发者自定义的模板类型（template type）渲染不同的子组件。\\n\\n  适用于不同结构的组件可以提前把结构定义在模板template中，简化UI结构\\n\\n**Repeat也可以看成是LazyForEach的升级版。**\\n\\n\\n\\n\\n## 核心概念\\n\\n| 关键字        | 说明                                       |\\n| ------------- | ------------------------------------------ |\\n| each          | 渲染普通节点                               |\\n| templateId    | 指定要使用的模板的id                       |\\n| template      | 模板                                       |\\n| key           | 要循环渲染的节点的唯一标志                 |\\n| virtualScroll | 打开懒加载，totalCount为期望加载的数据长度 |\\n| onMove        | 列表项拖拽事件                             |\\n| cachedCount   | 设置预加载数量和是否开启动画-默认开启      |\\n\\n\\n\\n\\n## 组件复用的基本原理\\n\\nRepeat根据当前的有效加载范围（**屏幕可视区域**+**预加载区域**）按需创建子组件\\n\\n![image-20250624000205754](assets/image-20250624000205754.png)\\n\\n\\n\\n## 组件复用的过程\\n\\n### 首次渲染时\\n\\n![image-20250624000418732](assets/image-20250624000418732.png)\\n\\n- L1缓存为Repeat有效加载区域\\n- L2缓存为每个循环渲染模板的空闲节点缓存池。\\n\\n\\n\\n### 开始滑动列表\\n\\n将屏幕向右滑动（屏幕内容右移）一个节点的距离，Repeat将开始复用缓存池中的节点。index=10的节点进入有效加载范围，计算\\n\\n出其template type为bb。由于bb缓存池非空，Repeat会从bb缓存池中取出一个空闲节点进行复用，更新其节点属性，该子组件中涉\\n\\n及数据item和索引index的其他孙子组件会根据V2状态管理的规则做同步更新。其他节点仍在有效加载范围，均只更新索引index。\\n\\nindex=0的节点滑出了有效加载范围。当UI主线程空闲时，会检查aa缓存池是否已满，此时aa缓存池未满，将该节点加入到对应的缓\\n\\n存池中。\\n\\n如果此时对应template type的缓存池已满，Repeat会销毁掉多余的节点。\\n\\n![image-20250624000707881](assets/image-20250624000707881.png)\\n\\n### 数据更新\\n\\n删除index=4的节点，修改节点数据item_7为new_7。\\n\\n首先，删除index=4的节点后，失效节点加入aa缓存池。后面的列表节点前移，新进入有效加载区域的节点item_11会复用bb缓存池\\n\\n中的空闲节点，其他节点均只更新索引index。\\n\\n![image-20250624000734163](assets/image-20250624000734163.png)\\n\\n\\n\\n最后，节点item_5前移，索引index更新为4。根据template type的计算规则，节点item_5的template type变为aa，需要从aa缓存池中复用空闲节点，并且将旧节点加入bb缓存池\\n\\n![image-20250624000807035](assets/image-20250624000807035.png)\\n\\n## 基本使用\\n\\n对于结构固定的组件，可以使用Repeat和each的简单搭配\\n\\n\`\`\`typescript\\n// 在List容器组件中使用Repeat\\n@Entry\\n@ComponentV2\\n  // 推荐使用V2装饰器\\nstruct RepeatExample {\\n  @Local dataArr: Array<string> = []; // 数据源\\n\\n  aboutToAppear(): void {\\n    for (let i = 0; i < 50; i++) {\\n      this.dataArr.push(\`data_\${i}\`); // 模拟动态加载数据\\n    }\\n  }\\n\\n  build() {\\n    Column() {\\n      List() {\\n        Repeat<string>(this.dataArr)\\n          .each((ri: RepeatItem<string>) => {\\n            ListItem() {\\n              Text('each_' + ri.item).fontSize(30)\\n            }\\n          })\\n          .virtualScroll({ totalCount: this.dataArr.length }) // 打开懒加载，totalCount为期望加载的数据长度\\n      }\\n      .cachedCount(2) // 容器组件的预加载区域大小\\n      .height('70%')\\n      .border({ width: 1 }) // 边框\\n    }\\n  }\\n}\\n\`\`\`\\n\\n### 效果\\n\\n![0000000000011111111.20250620155133.75981077787316035971410601430804](assets/0000000000011111111.20250620155133.75981077787316035971410601430804.png)\\n\\n\\n\\n## 搭配template使用\\n\\n- templateId指定模板id\\n\\n- template声明模板\\n\\n\`\`\`typescript\\n// 在List容器组件中使用Repeat\\n@Entry\\n@ComponentV2\\n  // 推荐使用V2装饰器\\nstruct RepeatExampleWithTemplates {\\n  @Local dataArr: Array<string> = []; // 数据源\\n\\n  aboutToAppear(): void {\\n    for (let i = 0; i < 50; i++) {\\n      this.dataArr.push(\`data_\${i}\`); // 为数组添加一些数据\\n    }\\n  }\\n\\n  build() {\\n    Column() {\\n      List() {\\n        Repeat<string>(this.dataArr)\\n          .each((ri: RepeatItem<string>) => { // 默认渲染模板\\n            ListItem() {\\n              Text('each_' + ri.item).fontSize(30).fontColor('rgb(161,10,33)') // 文本颜色为红色\\n            }\\n          })\\n          .key((item: string, index: number): string => JSON.stringify(item)) // 键值生成函数\\n          .virtualScroll({ totalCount: this.dataArr.length }) // 打开懒加载，totalCount为期望加载的数据长度\\n          .templateId((item: string, index: number): string => { // 根据返回值寻找对应的模板子组件进行渲染\\n            return index <= 4 ? 'A' : (index <= 10 ? 'B' : ''); // 前5个节点模板为A，接下来的5个为B，其余为默认模板\\n          })\\n          .template('A', (ri: RepeatItem<string>) => { // 'A'模板\\n            ListItem() {\\n              Text('A_' + ri.item).fontSize(30).fontColor('rgb(23,169,141)') // 文本颜色为绿色\\n            }\\n          }, { cachedCount: 3 }) // 'A'模板的缓存列表容量为3\\n          .template('B', (ri: RepeatItem<string>) => { // 'B'模板\\n            ListItem() {\\n              Text('B_' + ri.item).fontSize(30).fontColor('rgb(39,135,217)') // 文本颜色为蓝色\\n            }\\n          }, { cachedCount: 4 }) // 'B'模板的缓存列表容量为4\\n      }\\n      .cachedCount(2) // 容器组件的预加载区域大小\\n      .height('70%')\\n      .border({ width: 1 }) // 边框\\n    }\\n  }\\n}\\n\`\`\`\\n\\n### 效果\\n\\n![0000000000011111111.20250620155133.56282241275264687848543582566127](assets/0000000000011111111.20250620155133.56282241275264687848543582566127.png)\\n\\n### 更多使用场景\\n\\n> [链接](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/arkts-new-rendering-control-repeat#%E6%8B%96%E6%8B%BD%E6%8E%92%E5%BA%8F)\\n\\n![image-20250624001130167](assets/image-20250624001130167.png)\\n\\n## 特别注意\\n\\n### 节点更新说明\\n\\nRepeat子组件的节点操作分为四种：节点创建、节点更新、节点复用、节点销毁。其中，节点更新和节点复用的区别为：\\n\\n- 节点更新：节点不销毁，状态变量驱动节点属性更新。\\n- 节点复用：旧节点不销毁，存储在空闲节点缓存池；需要创建新节点时，直接从缓存池中获取可复用的旧节点，并做相应的节点属性更新。\\n\\n\\n\\n### 使用限制\\n\\n## 使用限制\\n\\n- Repeat必须在滚动类容器组件内使用，仅有[List](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-list)、[Grid](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-grid)、[Swiper](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-swiper)以及[WaterFlow](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-waterflow)组件支持Repeat懒加载场景。\\n\\n  循环渲染只允许创建一个子组件，子组件应当是允许包含在容器组件中的子组件。例如：Repeat与[List](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-list)组件配合使用时，子组件必须为[ListItem](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-container-listitem)组件。\\n\\n- Repeat不支持V1装饰器，混用V1装饰器会导致渲染异常。\\n\\n- 滚动容器组件内只能包含一个Repeat。以List为例，同时包含ListItem、ForEach、LazyForEach的场景是不推荐的；同时包含多个Repeat也是不推荐的。\\n\\n- 当Repeat与自定义组件或[@Builder](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/arkts-builder)函数混用时，必须将RepeatItem类型整体进行传参，组件才能监听到数据变化。详见[Repeat与@Builder混用](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/arkts-new-rendering-control-repeat#repeat与builder混用)。\\n\\n\\n\\n## 关于我们\\n\\n[关于青蓝逐码组织](https://link.juejin.cn/?target=https%3A%2F%2Fwww.qinglanzhuma.cn%2F)\\n\\n如果你兴趣想要了解更多的鸿**蒙应用开发细节和最新资讯**，**甚至你想要做出一款属于自己的应用**！欢迎在评论区留言或者私信或者看我个人信息，可以加入技术交流群。\\n\\n![image-20250622200325374](assets/image-20250622200325374.png)\\n\\n"}`),o={name:"鸿蒙开发技巧/HarmonyOS Repeat 可复用的循环渲染/HarmonyOS Repeat 可复用的循环渲染.md"};function c(y,s,m,F,b,u){return a(),n("div",null,[...s[0]||(s[0]=[t("",53)])])}const B=i(o,[["render",c]]);export{A as __pageData,B as default};
